using DriveOS.Modules.CurriculumPedagogy.Domain.LicenseCategories;using DriveOS.SharedKernel.Identifiers;using Microsoft.EntityFrameworkCore;
namespace DriveOS.Modules.CurriculumPedagogy.Infrastructure.Persistence.Repositories;
internal sealed class LicenseCategoryDefinitionRepository(CurriculumPedagogyDbContext db):ILicenseCategoryDefinitionRepository
{public Task<LicenseCategoryDefinition?> GetByIdAsync(LicenseCategoryDefinitionId id,CancellationToken ct=default)=>db.LicenseCategories.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id,ct);public Task<LicenseCategoryDefinition?> GetByIdForUpdateAsync(LicenseCategoryDefinitionId id,CancellationToken ct=default)=>db.LicenseCategories.SingleOrDefaultAsync(x=>x.Id==id,ct);public Task<LicenseCategoryDefinition?> GetActiveByScopeAsync(OrganizationId org,string country,string code,CancellationToken ct=default)=>db.LicenseCategories.AsNoTracking().SingleOrDefaultAsync(x=>x.OrganizationId==org&&x.CountryCode==country.Trim().ToUpperInvariant()&&x.Code==code.Trim().ToUpperInvariant()&&x.Status==LicenseCategoryDefinitionStatus.Active,ct);public Task<bool> ExistsAsync(OrganizationId org,string country,string code,CancellationToken ct=default)=>db.LicenseCategories.AsNoTracking().AnyAsync(x=>x.OrganizationId==org&&x.CountryCode==country.Trim().ToUpperInvariant()&&x.Code==code.Trim().ToUpperInvariant(),ct);public async Task AddAsync(LicenseCategoryDefinition x,CancellationToken ct=default)=>await db.LicenseCategories.AddAsync(x,ct);}
